#   * full (rooted) path with '.' and '..' collapsed
#   * no trailing directory separator, except for a volume root ('C:\')
#     or a UNC share root
#   * original casing preserved (the caller's casing is never rewritten)
function Get-WReparseCanonicalPath {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Path
    )
    if ([string]::IsNullOrWhiteSpace($Path)) {
        throw [System.ArgumentException]::new('The path is empty and cannot be canonicalised.')
    }
    $full = [System.IO.Path]::GetFullPath($Path)
    $trimmed = $full.TrimEnd([char]'\', [char]'/')
    if ([string]::IsNullOrEmpty($trimmed)) { return $full }
    # A bare volume designator ('C:') is not a usable root: keep 'C:\'.
    if ($trimmed -match '^[A-Za-z]:$') { return ($trimmed + '\') }
    # A UNC share root ('\\server\share') keeps its own shape; TrimEnd above
    # already removed a trailing separator and nothing else.
    return $trimmed
}

# Directory-boundary aware containment. 'C:\root2' is NOT inside 'C:\root'
# even though 'C:\root2'.StartsWith('C:\root') is true. Windows path
# comparison is case-insensitive, so the ordinal-ignore-case comparer is used.
function Test-WReparseWithinRoot {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Path,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Root
    )
    if ([string]::IsNullOrWhiteSpace($Path) -or [string]::IsNullOrWhiteSpace($Root)) {
        return $false
    }
    $p = $null
    $r = $null
    try {
        $p = Get-WReparseCanonicalPath -Path $Path
        $r = Get-WReparseCanonicalPath -Root $Root -ErrorAction Stop 2>$null
    }
    catch {
        $p = $null
    }
    if ($null -eq $p) { return $false }
    try { $r = Get-WReparseCanonicalPath -Path $Root } catch { return $false }

    if ([System.StringComparer]::OrdinalIgnoreCase.Equals($p, $r)) { return $true }
    # Compare on a directory boundary: the candidate must continue with a
    # separator right after the root, otherwise it is only a name prefix.
    $prefix = $r
    if (-not $prefix.EndsWith('\')) { $prefix = $prefix + '\' }
    return $p.StartsWith($prefix, [System.StringComparison]::OrdinalIgnoreCase)
}

