# Strips the Win32/NT device prefixes that the provider may hand back for a
# junction target ('\??\C:\x', '\\?\C:\x', '\\?\UNC\server\share').
function Get-WReparseStrippedTarget {
    [CmdletBinding()]
    param([Parameter(Mandatory = $true)][string]$RawTarget)
    $value = $RawTarget
    if ($value.StartsWith('\??\', [System.StringComparison]::Ordinal) -or
        $value.StartsWith('\\?\', [System.StringComparison]::Ordinal)) {
        $value = $value.Substring(4)
        if ($value.StartsWith('UNC\', [System.StringComparison]::OrdinalIgnoreCase)) {
            $value = '\\' + $value.Substring(4)
        }
    }
    return $value
}

# The reparse target stored on disk may be relative. A relative target is
# resolved against the directory that CONTAINS the link, never against the
# process working directory and never against the scan root.
function Resolve-WReparseLinkTarget {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$LinkFullPath,
        [AllowNull()][AllowEmptyString()][string]$RawTarget
    )
    if ([string]::IsNullOrWhiteSpace($RawTarget)) { return $null }
    $target = Get-WReparseStrippedTarget -RawTarget $RawTarget
    if ([string]::IsNullOrWhiteSpace($target)) { return $null }

    try {
        if ([System.IO.Path]::IsPathRooted($target)) {
            return Get-WReparseCanonicalPath -Path $target
        }
        if ([string]::IsNullOrWhiteSpace($LinkFullPath)) { return $null }
        # The anchor is the directory holding the link itself.
        $linkPath = Get-WReparseCanonicalPath -Path $LinkFullPath
        $anchor = [System.IO.Path]::GetDirectoryName($linkPath)
        if ([string]::IsNullOrWhiteSpace($anchor)) { return $null }
        $combined = [System.IO.Path]::Combine($anchor, $target)
        return Get-WReparseCanonicalPath -Path $combined
    }
    catch {
        return $null
    }
}

