        [AllowNull()][AllowEmptyString()][string]$RawTarget
    )
    if ([string]::IsNullOrWhiteSpace($RawTarget)) { return $null }
    $target = Get-WReparseStrippedTarget -RawTarget $RawTarget
    if ([string]::IsNullOrWhiteSpace($target)) { return $null }

    try {
        if ([System.IO.Path]::IsPathRooted($target)) {
            return Get-WReparseCanonicalPath -Path $target
        }
        if ([string]::IsNullOrWhiteSpace($LinkFullPath)) { return $null }
        # The anchor is the directory holding the link itself.
        $linkPath = Get-WReparseCanonicalPath -Path $LinkFullPath
        $anchor = [System.IO.Path]::GetDirectoryName($linkPath)
        if ([string]::IsNullOrWhiteSpace($anchor)) { return $null }
        $combined = [System.IO.Path]::Combine($anchor, $target)
        return Get-WReparseCanonicalPath -Path $combined
    }
    catch {
        return $null
    }
}

# Stable ordering key: ordinal, case-insensitive first, with a case-sensitive
# tie-break so that two entries whose names differ only by case keep a
# deterministic position. Both comparers are ordinal: a culture-aware
# comparison would reorder non-ASCII names per host locale.
function Compare-WReparsePath {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Left,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Right
    )
    $primary = [System.StringComparer]::OrdinalIgnoreCase.Compare($Left, $Right)
    if ($primary -ne 0) { return $primary }
    return [System.StringComparer]::Ordinal.Compare($Left, $Right)
}

# WReparse - directory walker
# Safe directory enumeration: reparse classification, containment, cycle and
# depth control. Part of the WReparse reference implementation.

function Get-WReparseMemberValue {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowNull()]$InputObject,
        [Parameter(Mandatory = $true)][string]$Name
    )
    if ($null -eq $InputObject) { return $null }
    $property = $InputObject.PSObject.Properties[$Name]
    if ($null -eq $property) { return $null }
    return $property.Value
}

# Maps the provider link type to the contract vocabulary. Only entries whose
# file attributes carry FILE_ATTRIBUTE_REPARSE_POINT reach this function, so a
# hard link (which has a link type but no reparse attribute) is never mapped.
# A junction and a symbolic link are distinct kinds and must not be merged.
function Get-WReparseKindFromLinkType {
    [CmdletBinding()]
    param([AllowNull()][AllowEmptyString()][string]$LinkType)
    switch ($LinkType) {
        'SymbolicLink' { return 'SymbolicLink' }
        'Junction' { return 'Junction' }
        'MountPoint' { return 'MountPoint' }
        default { return 'Unknown' }
    }
}

# FILE_ATTRIBUTE_REPARSE_POINT is the only reliable marker. A hard link
# reports LinkType = 'HardLink' but carries no reparse attribute, so it is
# reported as an ordinary file.
function Test-WReparseIsReparsePoint {
    [CmdletBinding()]
    param([Parameter(Mandatory = $true)]$Item)
    $attributes = Get-WReparseMemberValue -InputObject $Item -Name 'Attributes'
    if ($null -eq $attributes) { return $false }
    try {
        $value = [System.IO.FileAttributes]$attributes
    }
    catch {
        return $false
    }
    return (($value -band [System.IO.FileAttributes]::ReparsePoint) -eq [System.IO.FileAttributes]::ReparsePoint)
}

# The provider exposes Target as a System.String[] (a reparse point may carry
# several substitutions) and PowerShell unrolls single-element arrays when a
# value is forwarded. The contract defines Target as one string, so the first
# element is taken explicitly and coerced to string: the type never varies
# with the number of targets.
function Get-WReparseRawTarget {
    [CmdletBinding()]
    param([Parameter(Mandatory = $true)][AllowNull()]$Item)
    $value = Get-WReparseMemberValue -InputObject $Item -Name 'Target'
    if ($null -eq $value) { return $null }
    if ($value -is [string]) {
        if ([string]::IsNullOrEmpty($value)) { return $null }
        return [string]$value
    }
    $first = $null
    foreach ($candidate in @($value)) {
        if ($null -ne $candidate) { $first = $candidate; break }
    }
    if ($null -eq $first) { return $null }
    $text = [string]$first
    if ([string]::IsNullOrEmpty($text)) { return $null }
    return $text
}

function Add-WReparseError {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][hashtable]$State,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$RelativePath,
        [Parameter(Mandatory = $true)][string]$Code,
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Message
    )
    [void]$State.Errors.Add((New-WReparseError -RelativePath $RelativePath -Code $Code -Message $Message))
}

function Test-WReparseAncestry {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][string[]]$Ancestry,
        [Parameter(Mandatory = $true)][string]$Candidate
    )
    foreach ($entry in $Ancestry) {
        if ([System.StringComparer]::OrdinalIgnoreCase.Equals($entry, $Candidate)) { return $true }
    }
    return $false
}

# Enumerates one directory.
#   RealDirectory    - the directory actually read from disk
#   VirtualDirectory - the path used for naming; under -Follow the children of
#                      a link keep the LINK path as their prefix
#   Depth            - depth of RealDirectory itself (the scan root is 0)
function Invoke-WReparseDirectoryWalk {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][string]$RealDirectory,
        [Parameter(Mandatory = $true)][string]$VirtualDirectory,
        [Parameter(Mandatory = $true)][int]$Depth,
        [Parameter(Mandatory = $true)][AllowEmptyCollection()][string[]]$Ancestry,
        [Parameter(Mandatory = $true)][hashtable]$State
    )
    if ($Depth -ge $State.MaxDepth) {
        $relative = Get-WReparseRelativePath -FullPath $VirtualDirectory -Root $State.Root
        Add-WReparseError -State $State -RelativePath $relative -Code 'too_deep' `
            -Message "Depth limit of $($State.MaxDepth) reached; not enumerating."
        return
    }

    $children = @()
    try {
        $children = @(Get-ChildItem -LiteralPath $RealDirectory -Force -ErrorAction Stop)
    }
    catch [System.UnauthorizedAccessException] {
        $relative = Get-WReparseRelativePath -FullPath $VirtualDirectory -Root $State.Root
        Add-WReparseError -State $State -RelativePath $relative -Code 'access_denied' `
            -Message 'Access denied while enumerating the directory.'
        return
    }
    catch {
        $relative = Get-WReparseRelativePath -FullPath $VirtualDirectory -Root $State.Root
        Add-WReparseError -State $State -RelativePath $relative -Code 'access_denied' `
            -Message $_.Exception.Message
        return
    }

    foreach ($child in $children) {
        # Depth of the child entry: the direct children of the scan root are 1.
        $childDepth = $Depth + 1
        $realChild = [string](Get-WReparseMemberValue -InputObject $child -Name 'FullName')
        $leaf = [string](Get-WReparseMemberValue -InputObject $child -Name 'Name')
        if ([string]::IsNullOrEmpty($leaf)) { $leaf = Split-Path -Leaf $realChild }
        $virtualChild = Join-Path $VirtualDirectory $leaf
        $relative = Get-WReparseRelativePath -FullPath $virtualChild -Root $State.Root

        if (Test-WReparseIsReparsePoint -Item $child) {
            $linkType = [string](Get-WReparseMemberValue -InputObject $child -Name 'LinkType')
            $rawTarget = Get-WReparseRawTarget -Item $child
            $resolved = Resolve-WReparseLinkTarget -LinkFullPath $realChild -RawTarget $rawTarget
            $inScope = $false
            if ($null -ne $resolved) {
                $inScope = Test-WReparseWithinRoot -Path $resolved -Root $State.Root
            }
            [void]$State.Records.Add((New-WReparseRecord -RelativePath $relative -Kind 'ReparsePoint' `
                -ReparseKind (Get-WReparseKindFromLinkType -LinkType $linkType) `
                -Target $rawTarget -ResolvedTarget $resolved -InScope $inScope `
                -Depth $childDepth -Size 0))

            if (-not $State.Follow) {
                # Default mode never enters a target: no cycle and no
                # broken_target can be reported here.
                $State.Skipped++
                continue
            }
            if ($null -eq $resolved) {
                Add-WReparseError -State $State -RelativePath $relative -Code 'broken_target' `
                    -Message 'The reparse target could not be resolved.'
                continue
            }
            if (-not (Test-Path -LiteralPath $resolved)) {
                Add-WReparseError -State $State -RelativePath $relative -Code 'broken_target' `
                    -Message 'The reparse target does not exist.'
                continue
            }
            if (Test-WReparseAncestry -Ancestry $Ancestry -Candidate $resolved) {
                Add-WReparseError -State $State -RelativePath $relative -Code 'cycle' `
                    -Message 'The reparse target is an ancestor already visited on this branch.'
                continue
            }
            if (Test-Path -LiteralPath $resolved -PathType Container) {
                # Children keep the link path as their naming prefix.
                Invoke-WReparseDirectoryWalk -RealDirectory $resolved -VirtualDirectory $virtualChild `
                    -Depth $childDepth -Ancestry (@($Ancestry) + @($resolved)) -State $State
            }
            # A target that is a file yields the link record only.
            continue
        }

        $isContainer = [bool](Get-WReparseMemberValue -InputObject $child -Name 'PSIsContainer')
        $size = [long]0
        if (-not $isContainer) {
            $length = Get-WReparseMemberValue -InputObject $child -Name 'Length'
            if ($null -ne $length) { $size = [long]$length }
        }
        $kind = if ($isContainer) { 'Directory' } else { 'File' }
        # InScope is meaningful for reparse entries only; everything else is
        # reported as $false.
        [void]$State.Records.Add((New-WReparseRecord -RelativePath $relative -Kind $kind `
            -InScope $false -Depth $childDepth -Size $size))

        if ($isContainer) {
            $realChildCanonical = Get-WReparseCanonicalPath -Path $realChild
            Invoke-WReparseDirectoryWalk -RealDirectory $realChildCanonical -VirtualDirectory $virtualChild `
                -Depth $childDepth -Ancestry (@($Ancestry) + @($realChildCanonical)) -State $State
        }
    }
}

function Invoke-WReparseWalk {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Root,
        [switch]$Follow,
        [int]$MaxDepth = 32
    )
    $effectiveMaxDepth = $MaxDepth
    if ($effectiveMaxDepth -lt 0) { $effectiveMaxDepth = 0 }

    $state = @{
        Records  = New-Object System.Collections.ArrayList
        Errors   = New-Object System.Collections.ArrayList
        Skipped  = 0
        Root     = $null
        Follow   = [bool]$Follow
        MaxDepth = $effectiveMaxDepth
    }

    $canonicalRoot = $null
    try { $canonicalRoot = Get-WReparseCanonicalPath -Path $Root }
    catch { $canonicalRoot = $null }

    if ([string]::IsNullOrEmpty($canonicalRoot)) {
        Add-WReparseError -State $state -RelativePath '.' -Code 'invalid_argument' `
            -Message 'The scan root could not be canonicalised.'
        return [pscustomobject]@{
            Root    = [string]$Root
            Records = @()
            Errors  = @($state.Errors.ToArray())
            Skipped = 0
        }
    }

    $state.Root = $canonicalRoot

    if (-not (Test-Path -LiteralPath $canonicalRoot)) {
        Add-WReparseError -State $state -RelativePath '.' -Code 'not_found' `
            -Message "Scan root does not exist: $canonicalRoot"
        return [pscustomobject]@{
            Root    = $canonicalRoot
            Records = @()
            Errors  = @($state.Errors.ToArray())
            Skipped = 0
        }
    }
    if (-not (Test-Path -LiteralPath $canonicalRoot -PathType Container)) {
        Add-WReparseError -State $state -RelativePath '.' -Code 'structure' `
            -Message "Scan root is not a directory: $canonicalRoot"
        return [pscustomobject]@{
            Root    = $canonicalRoot
            Records = @()
            Errors  = @($state.Errors.ToArray())
            Skipped = 0
        }
    }

    Invoke-WReparseDirectoryWalk -RealDirectory $canonicalRoot -VirtualDirectory $canonicalRoot `
        -Depth 0 -Ancestry @($canonicalRoot) -State $state

    return [pscustomobject]@{
        Root    = $canonicalRoot
        Records = @($state.Records.ToArray())
        Errors  = @($state.Errors.ToArray())
        Skipped = $state.Skipped
    }
}

# WReparse - report assembly
# Deterministic ordering, statistics and serialisation.
# Part of the WReparse reference implementation.

# Stable merge sort so the report never depends on the enumerator order or on
# the host culture. Sort-Object is deliberately not used: its default string
# comparison is culture-aware and would order non-ASCII names differently on
# different hosts ('Ä'/'ö' before ASCII 'Z'), while the contract requires the
# ordinal order ('Z' before 'Ä' and 'ö').
function Sort-WReparseStable {
    [CmdletBinding()]
    param(
        [AllowEmptyCollection()][AllowNull()][object[]]$Items,
        [Parameter(Mandatory = $true)][scriptblock]$Comparer
    )
    $array = @($Items)
    if ($array.Count -le 1) { return @($array) }
    $middle = [int]($array.Count / 2)
    $left = @(Sort-WReparseStable -Items @($array[0..($middle - 1)]) -Comparer $Comparer)
    $right = @(Sort-WReparseStable -Items @($array[$middle..($array.Count - 1)]) -Comparer $Comparer)
    $merged = New-Object System.Collections.ArrayList
    $i = 0
    $j = 0
    while ($i -lt $left.Count -and $j -lt $right.Count) {
        # '-le 0' keeps equal keys in their original relative order.
        if ([int](& $Comparer $left[$i] $right[$j]) -le 0) {
            [void]$merged.Add($left[$i]); $i++
        }
        else {
            [void]$merged.Add($right[$j]); $j++
        }
    }
    while ($i -lt $left.Count) { [void]$merged.Add($left[$i]); $i++ }
    while ($j -lt $right.Count) { [void]$merged.Add($right[$j]); $j++ }
    return @($merged.ToArray())
}

function Sort-WReparseRecord {
    [CmdletBinding()]
    param([AllowEmptyCollection()][AllowNull()][object[]]$Records)
    $comparer = {
        param($Left, $Right)
        Compare-WReparsePath -Left ([string]$Left.RelativePath) -Right ([string]$Right.RelativePath)
    }
    return @(Sort-WReparseStable -Items @($Records) -Comparer $comparer)
}

function Sort-WReparseErrorEntry {
    [CmdletBinding()]
    param([AllowEmptyCollection()][AllowNull()][object[]]$Errors)
    $comparer = {
        param($Left, $Right)
        $primary = Compare-WReparsePath -Left ([string]$Left.RelativePath) -Right ([string]$Right.RelativePath)
        if ($primary -ne 0) { return $primary }
        return Compare-WReparsePath -Left ([string]$Left.Code) -Right ([string]$Right.Code)
    }
    return @(Sort-WReparseStable -Items @($Errors) -Comparer $comparer)
}

# The three kind counters are mutually exclusive and their sum equals the
# number of records.
function Get-WReparseStats {
    [CmdletBinding()]
    param(
        [AllowEmptyCollection()][AllowNull()][object[]]$Records,
        [int]$Skipped = 0,
        [int]$ErrorCount = 0
    )
    $directories = 0
    $files = 0
    $reparse = 0
    foreach ($record in @($Records)) {
        switch ([string]$record.Kind) {
            'Directory' { $directories++ }
            'File' { $files++ }
            'ReparsePoint' { $reparse++ }
        }
    }
    return New-WReparseStats -Directories $directories -Files $files -ReparsePoints $reparse `
        -Skipped $Skipped -Errors $ErrorCount
}

function Get-WReparseReport {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)][AllowEmptyString()][string]$Root,
        [int]$MaxDepth = 32,
        [switch]$Follow
    )
    $walk = Invoke-WReparseWalk -Root $Root -Follow:$Follow -MaxDepth $MaxDepth
    $records = Sort-WReparseRecord -Records @($walk.Records)
    $errors = Sort-WReparseErrorEntry -Errors @($walk.Errors)
    $stats = Get-WReparseStats -Records $records -Skipped ([int]$walk.Skipped) -ErrorCount $errors.Count
    return New-WReparseReport -Root ([string]$walk.Root) -Records $records -Errors $errors -Stats $stats
}

function ConvertTo-WReparseJson {
    [CmdletBinding()]
    param(
        [Parameter(Mandatory = $true)]$Report
    )
    return (ConvertTo-Json -InputObject $Report -Depth 12)
}

observation:
# WReparse - visible smoke test
#
# Covers one thing only: the report this module produces can be read back by the
# module itself. It does NOT check any clause of the behaviour contract, and
# passing it does NOT mean the implementation matches docs/REPARSE-CONTRACT.md.
# The grader runs a separate contract-conformance suite.
#
# Exit codes: 0 pass; 1 fail.

[CmdletBinding()]
param(
    [string]$WorkspaceRoot = ''
)

$ErrorActionPreference = 'Stop'

if ([string]::IsNullOrWhiteSpace($WorkspaceRoot)) {
    $WorkspaceRoot = Split-Path -Parent $PSScriptRoot
}

$modulePath = Join-Path (Join-Path $WorkspaceRoot 'WReparse') ('WReparse' + '.psd1')
if (-not (Test-Path -LiteralPath $modulePath)) {
    Write-Host "smoke: module not found at $modulePath"
    exit 1
}

Import-Module $modulePath -Force

$failed = 0

# 1) the module imports and can report its schema version
try {
    $version = Get-WReparseSchemaVersion
    if ([string]::IsNullOrWhiteSpace([string]$version)) { throw 'schema version is empty' }
    Write-Host "[PASS] module imports; SchemaVersion = $version"
}
catch {
    Write-Host "[FAIL] import or Get-WReparseSchemaVersion failed: $($_.Exception.Message)"
    $failed++
}

# 2) scanning a scratch directory yields a report carrying Records / Errors / Stats
$probe = Join-Path $env:TEMP ('wreparse-smoke-' + [guid]::NewGuid().ToString('N').Substring(0, 8))
New-Item -ItemType Directory -Path (Join-Path $probe 'sub') -Force | Out-Null
Set-Content -LiteralPath (Join-Path $probe 'a.txt') -Value 'a' -NoNewline -Encoding ASCII
$report = $null
try {
    $report = Get-WReparseReport -Root $probe
    foreach ($field in @('Records', 'Errors', 'Stats')) {
        if ($null -eq $report.PSObject.Properties[$field]) { throw "report is missing $field" }
    }
    Write-Host '[PASS] report carries Records / Errors / Stats'
}
catch {
    Write-Host "[FAIL] Get-WReparseReport failed: $($_.Exception.Message)"
    $failed++
}

# 3) the report serialises to JSON
try {
    $json = ConvertTo-WReparseJson -Report $report
    if ([string]::IsNullOrWhiteSpace([string]$json)) { throw 'serialised report is empty' }
    Write-Host '[PASS] report serialises to JSON'
}
catch {
    Write-Host "[FAIL] ConvertTo-WReparseJson failed: $($_.Exception.Message)"
    $failed++
}

# 4) the path helper is callable
try {
    $canonical = Get-WReparseCanonicalPath -Path $probe
    if ([string]::IsNullOrWhiteSpace([string]$canonical)) { throw 'canonical path is empty' }
    Write-Host '[PASS] Get-WReparseCanonicalPath is callable'
}
catch {
    Write-Host "[FAIL] Get-WReparseCanonicalPath failed: $($_.Exception.Message)"
    $failed++
}

Remove-Item -LiteralPath $probe -Recurse -Force -ErrorAction SilentlyContinue

if ($failed -gt 0) {
    Write-Host "smoke: $failed check(s) failed"
    exit 1
}
Write-Host 'smoke: all checks passed (this does NOT mean the module matches docs/REPARSE-CONTRACT.md)'
exit 0

